/bin/zsh -lc "python3.12 -B -c 'from solution import reconcile
from itertools import product
import copy
invalid = [None, [], 1, {}, {\"entity\":\"\",\"version\":0,\"payload\":0}, {\"entity\":1,\"version\":0,\"payload\":0}]
invalid += [{\"entity\":\"a\",\"version\":v,\"payload\":0} for v in (None, True, False, -1, 1.0, \"1\")]
invalid += [{\"entity\":\"a\",\"version\":0,\"deleted\":v,\"payload\":0} for v in (None, 0, 1, \"\", [])]
invalid += [{\"entity\":\"a\",\"version\":0}]
count = 0
for bad in invalid:
 for prefix in ([], [{\"entity\":\"a\",\"version\":99,\"payload\":\"winner\"}]):
  try: reconcile(iter(prefix + [bad]))
  except ValueError: count += 1
  else: raise AssertionError((\"invalid accepted\", bad))
print(\"Invalid-event checks passed:\", count)
pool = [{\"entity\":e,\"version\":v,\"deleted\":d, **({} if d else {\"payload\":(e,v)})} for e in (\"a\",\"A\",\" \") for v in (0,1) for d in (False,True)]
count = 0
for n in range(4):
 for seq in product(pool, repeat=n):
  expected = {}
  for entity in (\"a\",\"A\",\" \"):
   candidates = [(ev[\"version\"],i,ev) for i,ev in enumerate(seq) if ev[\"entity\"]==entity]
   if candidates:
    ev = max(candidates, key=lambda x:x[:2])[2]
    if not ev[\"deleted\"]: expected[entity] = ev[\"payload\"]
  assert reconcile(iter(seq)) == expected, seq
  count += 1
print(\"Ordering/ties/deletion/revival/identifier checks passed:\", count)
for payload in (None, False, 0, \"\", [], {}, {\"nested\":[{\"x\":[1]}]}):
 events = [{\"entity\":\"a\",\"version\":0,\"payload\":payload,\"ignored\":object()}]
 result = reconcile(iter(events))
 assert result == {\"a\":copy.deepcopy(payload)}
 if isinstance(payload, (dict,list)): assert result[\"a\"] is not payload
payload = {\"nested\":[{\"x\":[1]}]}
events = [{\"entity\":\"a\",\"version\":0,\"payload\":payload}]
result = reconcile(iter(events))
result[\"a\"][\"nested\"][0][\"x\"].append(2)
assert payload == {\"nested\":[{\"x\":[1]}]}
payload[\"nested\"][0][\"x\"].append(3)
assert result == {\"a\":{\"nested\":[{\"x\":[1,2]}]}}
print(\"Falsy payloads, ignored fields, and bidirectional nested isolation passed\")'"
